import {migrateDemoLabels} from './demo-labels.mjs';
import {money,endTime,eligibility,assign,respond,totals,active,minutes} from './domain.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',trophy:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v2a4 4 0 0 0 4 4 M16 5h4v2a4 4 0 0 1-4 4 M12 13v6 M8 21h8 M10 19h4',wallet:'M3 5h16v15H3z M3 5l13-3v3 M15 11h6v5h-6z M17 13.5h1',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',left:'M15 5l-7 7 7 7',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18L18 6',arrow:'M5 12h14 M13 6l6 6-6 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 11l3 3 5-6',mail:'M3 5h18v14H3z M3 5l9 7 9-7'};
const icon=k=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[k]||paths.grid}"/></svg>`;
const initials=n=>n.split(' ').slice(0,2).map(s=>s[0]).join('');
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parseDate=s=>new Date(s+'T12:00:00');
const addDays=(s,n)=>{const d=parseDate(s);d.setDate(d.getDate()+n);return localDate(d)};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Costa_Rica',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const monday=d=>addDays(d,-((parseDate(d).getDay()+6)%7));
const dateLabel=(s,opts={day:'numeric',month:'short'})=>parseDate(s).toLocaleDateString('es-CR',opts);
const weekLabel=s=>`${dateLabel(s,{day:'numeric'})}–${dateLabel(addDays(s,6),{day:'numeric',month:'long',year:'numeric'})}`;
const statuses={pending:['Pendiente','amber'],accepted:['Confirmado','green'],rejected:['Rechazado','red'],empty:['Sin asignar','gray']};
const badge=(text,color)=>`<span class="badge ${color}">${esc(text)}</span>`;
const statusBadge=s=>badge(...(statuses[s]||statuses.empty));
const uid=()=>crypto.randomUUID();
const KEY='arbitra-beta-v1';let storageOK=true;
function seed(){
 const week=monday(today());
 const names=['Andrés Solís','Daniel Vargas','María Rodríguez','José Alvarado','Luis Chaves','Valeria Rojas','Carlos Méndez','Sofía Quesada'];
 const refs=names.map((name,i)=>({id:'r'+i,name,email:`${name.split(' ')[0].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}@ejemplo.invalid`,level:i<4?'Primera categoría':'Segunda categoría',availability:Object.fromEntries(Array.from({length:7},(_,j)=>[addDays(week,j),{start:'06:00',end:'22:00'}]))}));
 refs[3].availability[addDays(week,5)]={start:'14:00',end:'22:00'};
 refs[6].availability[addDays(week,6)]={start:'06:00',end:'12:00'};
 const tournaments=[{id:'t1',name:'Copa Horizonte',organizer:'Comité deportivo local',category:'Fútbol 11 · Libre',refs:refs.map(r=>r.id)},{id:'t2',name:'Torneo Empresarial',organizer:'Organización empresarial',category:'Fútbol 7 · Libre',refs:refs.slice(0,6).map(r=>r.id)},{id:'t3',name:'Liga Juvenil Regional',organizer:'Comité de liga juvenil',category:'Fútbol 11 · Juvenil',refs:refs.slice(2).map(r=>r.id)}];
 const slot=(role,ref='',status='empty',fee=18000)=>({id:uid(),role,ref,status,fee,paid:false});
 const matches=[
 {id:'m1',tournament:'t1',home:'Deportivo Aurora',away:'Atlético Eclipse',date:addDays(week,5),time:'09:00',duration:120,venue:'Estadio Aurora · ubicación ficticia',lat:null,lng:null,charge:70000,collected:false,slots:[slot('Central','r0','pending',22000),slot('Asistente 1','r1','accepted',16000),slot('Asistente 2')]},
 {id:'m2',tournament:'t1',home:'Unión Cedros',away:'Sporting Cometa',date:addDays(week,5),time:'14:00',duration:120,venue:'Parque Deportivo Cedros · ubicación ficticia',lat:null,lng:null,charge:65000,collected:false,slots:[slot('Central','r2','accepted',22000),slot('Asistente 1','r3','accepted',16000),slot('Asistente 2','r4','accepted',16000)]},
 {id:'m3',tournament:'t2',home:'Titanes FC',away:'Deportivo Prisma',date:addDays(week,5),time:'16:00',duration:80,venue:'Complejo Prisma · ubicación ficticia',lat:null,lng:null,charge:35000,collected:true,slots:[slot('Central','r5','accepted',22000)]},
 {id:'m4',tournament:'t1',home:'Atlético Olivos',away:'Unión Estelar',date:addDays(week,6),time:'10:00',duration:120,venue:'Cancha Estelar · ubicación ficticia',lat:null,lng:null,charge:65000,collected:false,slots:[slot('Central'),slot('Asistente 1'),slot('Asistente 2')]},
 {id:'m5',tournament:'t3',home:'Academia Fénix',away:'Juvenil Centella',date:addDays(week,6),time:'14:00',duration:100,venue:'Estadio Centella · ubicación ficticia',lat:null,lng:null,charge:55000,collected:false,slots:[slot('Central','r2','pending',20000),slot('Asistente 1','r7','accepted',14000),slot('Asistente 2')]},
 {id:'m6',tournament:'t2',home:'Deportivo Atlas',away:'Halcones FC',date:addDays(week,4),time:'19:00',duration:80,venue:'Cancha Cometa · ubicación ficticia',lat:null,lng:null,charge:35000,collected:false,slots:[slot('Central','r0','accepted',22000)]}
 ];
 return {version:1,week,refs,tournaments,matches,events:[{text:'Beta lista para recorrer la primera jornada.',at:Date.now()}]};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY));if(!db||db.version!==1||!Array.isArray(db.matches)||!Array.isArray(db.refs)||!Array.isArray(db.tournaments))db=seed()}catch{db=seed();storageOK=false}
migrateDemoLabels(db);
let role='admin',view='overview',refId='r0',week=monday(today()),day='',filter='all',query='',financeTab='charges',tournamentFilter='all';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{storageOK=false;toast('El navegador no permitió guardar. Los cambios durarán mientras esté abierta esta página.')}}
function log(text){db.events.unshift({text,at:Date.now()});db.events=db.events.slice(0,30);persist()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function tournament(m){return db.tournaments.find(t=>t.id===m.tournament)}
function refName(id){return db.refs.find(r=>r.id===id)?.name||'Sin asignar'}
const matchState=m=>m.slots.every(s=>s.status==='accepted')?'accepted':m.slots.some(s=>s.status==='pending')?'pending':'empty';
const sorted=ms=>[...ms].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
const weekMatches=()=>sorted(db.matches.filter(m=>m.date>=week&&m.date<=addDays(week,6)));
const navs={admin:[['overview','grid','Resumen'],['matches','calendar','Partidos'],['tournaments','trophy','Torneos'],['refs','people','Árbitros'],['finance','wallet','Cobros y pagos']],ref:[['home','grid','Mis nombramientos'],['availability','calendar','Mi disponibilidad'],['history','wallet','Mis pagos']]};
const navTitle=()=>navs[role].find(n=>n[0]===view)?.[2]||'Resumen';
const weekButtons=()=>`<div class="week-controls"><button class="iconbtn" data-action="week-prev" aria-label="Semana anterior">${icon('left')}</button><span class="subtle">${weekLabel(week)}</span><button class="iconbtn" data-action="week-next" aria-label="Semana siguiente">${icon('chevron')}</button><button class="text-button" data-action="week-today">Esta semana</button></div>`;
function render(){
 const pending=db.matches.flatMap(m=>m.slots).filter(s=>s.status==='pending').length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand" aria-label="A"><span class="brand-mark">A</span></div><div class="workspace"><span class="avatar">AH</span><div style="font-size:11px">Asociación Horizonte<small>Espacio de demostración</small></div></div><div class="navlabel">${role==='admin'?'ADMINISTRACIÓN':'PORTAL DEL ÁRBITRO'}</div><nav class="nav" aria-label="Principal">${navs[role].map(([id,ico,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='matches'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="beta-box"><strong>Un espacio para probar</strong>Datos ficticios. Cambie de perfil para recorrer ambos lados del nombramiento.</div><button data-action="reset">${icon('reset')}Restablecer demostración</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Asociación Horizonte <span>/</span> <b>${navTitle()}</b></div><div class="top-right"><span class="demo-tag">BETA INTERACTIVA</span><label class="role-switch">${icon('shield')}<select id="role" aria-label="Cambiar perfil de demostración"><option value="admin" ${role==='admin'?'selected':''}>Administrador</option>${db.refs.map(r=>`<option value="${r.id}" ${role==='ref'&&refId===r.id?'selected':''}>Árbitro · ${esc(r.name)}</option>`).join('')}</select></label><div class="avatar">${role==='admin'?'AD':initials(refName(refId))}</div></div></header><div class="content">${content()}</div></main></div>`;
}
function head(eyebrow,title,subtitle,button=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`}
function stat(label,value,note,ico){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong><small>${note}</small></div>`}
function content(){
 if(role==='ref'){if(view==='availability')return availabilityPage();if(view==='history')return refHistory();return refereeHome()}
 if(view==='tournaments')return tournamentsPage();if(view==='refs')return refsPage();if(view==='finance')return financePage();return overview(view==='matches');
}
function overview(full=false){
 const matches=weekMatches(),confirmed=matches.filter(m=>matchState(m)==='accepted').length,pending=matches.flatMap(m=>m.slots).filter(s=>s.status==='pending').length,empty=matches.flatMap(m=>m.slots).filter(s=>!active(s)).length;
 const available=db.refs.filter(r=>Array.from({length:7},(_,i)=>addDays(week,i)).some(d=>r.availability[d])).length;
 return head(full?'PROGRAMACIÓN':'SU ASOCIACIÓN, AL DÍA',full?'Partidos de la jornada':'Todo listo para la próxima jornada',full?'Organice los partidos y complete cada equipo arbitral.':'Organice a su equipo. Que cada partido tenga a su árbitro.',`<button class="btn primary" data-action="new-match">${icon('plus')}Nuevo partido</button>`)+
 (!full?`<div class="stats">${stat('Partidos esta semana',matches.length,`${db.tournaments.length} torneos registrados`,'calendar')}${stat('Equipos arbitrales listos',confirmed,`<span>${confirmed}</span> de ${matches.length} partidos confirmados`,'check')}${stat('Invitaciones pendientes',pending,`${empty} puestos por cubrir`,'mail')}${stat('Árbitros con disponibilidad',available,`De ${db.refs.length} integrantes del panel`,'people')}</div>`:'')+
 `<div class="${full?'':'grid-main'}"><section class="panel"><div class="panel-header"><div><h2>${full?'Calendario de partidos':'La jornada'}</h2><p>${matches.length} partidos · ${empty} puestos por cubrir</p></div>${weekButtons()}</div>${weekStrip()}<div class="filterbar"><button class="chip ${filter==='all'?'active':''}" data-filter="all">Todos</button><button class="chip ${filter==='empty'?'active':''}" data-filter="empty">Por completar</button><button class="chip ${filter==='pending'?'active':''}" data-filter="pending">Pendientes</button><button class="chip ${filter==='accepted'?'active':''}" data-filter="accepted">Confirmados</button><span class="spacer"></span><input class="search" id="search" placeholder="Buscar equipo o torneo" aria-label="Buscar equipo o torneo" value="${esc(query)}"></div><div id="match-list">${matchList()}</div></section>${full?'':sidePanel(empty)}</div><div class="footnote">${icon('info')}Demostración con información ficticia. Los cambios se guardan ${storageOK?'en este navegador':'solo durante esta sesión'}; los perfiles se simulan y no se envían correos.</div>`;
}
function weekStrip(){return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(week,i);return `<button class="day ${day===d||(!day&&d===today())?'active':''}" data-day="${d}" aria-pressed="${day===d}"><span>${dateLabel(d,{weekday:'short'}).replace('.','').toUpperCase()}</span><b>${parseDate(d).getDate()}</b><i class="${db.matches.some(m=>m.date===d)?'':'blank'}"></i></button>`}).join('')}</div>`}
function matchList(){const items=weekMatches().filter(m=>(!day||m.date===day)&&(filter==='all'||(filter==='empty'?matchState(m)!=='accepted':matchState(m)===filter))&&`${m.home} ${m.away} ${tournament(m)?.name}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));return items.length?items.map(matchCard).join(''):emptyState('No hay partidos con estos filtros.','Pruebe otro día o agregue un nuevo partido.','calendar')}
function matchCard(m){const names=m.slots.filter(s=>s.status==='accepted').map(s=>refName(s.ref));return `<article class="match"><div class="match-top"><span class="tournament-tag">${esc(tournament(m)?.name)}</span>${badge(matchState(m)==='accepted'?'Equipo completo':matchState(m)==='pending'?'Esperando respuesta':'Por completar',statuses[matchState(m)][1])}</div><div class="teams"><span class="crest">${esc(initials(m.home))}</span>${esc(m.home)}<span class="versus">vs</span><span class="crest">${esc(initials(m.away))}</span>${esc(m.away)}</div><div class="match-meta"><span>${icon('calendar')}${dateLabel(m.date,{weekday:'short',day:'numeric',month:'short'})}</span><span>${icon('clock')}${esc(m.time)}–${endTime(m.time,m.duration)}</span><span>${icon('pin')}${esc(m.venue)}</span></div><div class="match-bottom"><div class="crew">${names.slice(0,3).map(n=>`<span class="avatar" title="${esc(n)}">${esc(initials(n))}</span>`).join('')}<small>${names.length}/${m.slots.length} confirmados</small></div><button class="btn secondary small" data-action="assign" data-id="${m.id}">${matchState(m)==='accepted'?'Ver nombramiento':'Asignar árbitros'}${icon('arrow')}</button></div></article>`}
function sidePanel(empty){return `<aside class="side-stack"><div class="insight"><div class="eyebrow">EL SIGUIENTE PASO</div><h2>${empty?'Cada puesto cuenta. Complete su jornada.':'Su equipo está listo para salir a la cancha.'}</h2><p>Consulte la disponibilidad y envíe invitaciones a los árbitros de su torneo.</p><button class="btn secondary small" data-action="unfilled">Ver puestos por cubrir ${icon('arrow')}</button></div><section class="panel"><div class="panel-header"><h2>Su panel arbitral</h2><button class="text-button" data-view="refs">Ver todos</button></div><div class="side-list">${db.refs.slice(0,4).map(r=>`<div class="side-row"><span class="avatar">${initials(r.name)}</span><div><b>${esc(r.name)}</b><small>${Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length} días disponibles esta semana</small></div><i class="mini-dot"></i></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>Actividad reciente</h2></div><div class="activity">${db.events.slice(0,4).map(e=>`<div class="activity-item"><i></i><div><b>${esc(e.text)}</b><br><span>${new Date(e.at).toLocaleTimeString('es-CR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Costa_Rica'})}</span></div></div>`).join('')}</div></section></aside>`}
function emptyState(title,subtitle='',ico='calendar'){return `<div class="empty">${icon(ico)}<b>${title}</b>${subtitle}</div>`}
function tournamentsPage(){return head('COMPETICIONES','Sus torneos, en un solo lugar','Defina el panel de árbitros disponible para cada competición.',`<button class="btn primary" data-action="new-tournament">${icon('plus')}Nuevo torneo</button>`)+`<div class="tournament-grid">${db.tournaments.map(t=>`<article class="tournament-card"><div class="trophy">${icon('trophy')}</div><span class="eyebrow">${esc(t.category)}</span><h2 style="margin-top:10px">${esc(t.name)}</h2><p>${esc(t.organizer)}</p><div class="numbers"><div><b>${db.matches.filter(m=>m.tournament===t.id).length}</b><small>Partidos</small></div><div><b>${t.refs.length}</b><small>Árbitros en el panel</small></div></div><div class="actions"><button class="btn secondary small" data-action="edit-tournament" data-id="${t.id}">Editar panel</button><button class="btn primary small" data-action="new-match" data-id="${t.id}">${icon('plus')}Partido</button></div></article>`).join('')}</div><p class="privacy-note">En esta beta, la asociación registra los partidos recibidos del organizador. El portal del organizador queda para una etapa posterior.</p>`}
function refsPage(){return head('EQUIPO ARBITRAL','Las personas detrás de cada partido','Revise la disponibilidad semanal y mantenga actualizado su panel.',`<button class="btn primary" data-action="new-ref">${icon('plus')}Agregar árbitro</button>`)+`<div class="toolbar">${weekButtons()}</div><div class="ref-grid">${db.refs.map(r=>`<article class="ref-card"><div class="person"><span class="avatar">${initials(r.name)}</span><div><b>${esc(r.name)}</b><div class="subtle" style="margin-top:4px">${esc(r.level)}</div></div></div><p>${esc(r.email)}</p><p>${db.tournaments.filter(t=>t.refs.includes(r.id)).length} torneos · ${db.matches.flatMap(m=>m.slots).filter(s=>s.ref===r.id&&s.status==='accepted').length} nombramientos confirmados</p>${badge(`${Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length} días disponibles`,'green')}<div class="actions" style="margin-top:17px"><button class="btn secondary small" data-action="see-availability" data-id="${r.id}">Ver disponibilidad</button><button class="text-button" data-action="as-ref" data-id="${r.id}">Probar su perfil ${icon('arrow')}</button></div></article>`).join('')}</div>`}
function availabilityRows(r,readonly=false){return Array.from({length:7},(_,i)=>{const date=addDays(week,i),a=r.availability[date];return `<div class="availability-day"><input type="checkbox" name="day-${date}" id="day-${date}" data-availability="${date}" ${a?'checked':''} ${readonly?'disabled':''} aria-label="Disponible el ${dateLabel(date)}"><label for="day-${date}">${dateLabel(date,{weekday:'long'})}<small>${dateLabel(date,{day:'numeric',month:'long'})}</small></label><input type="time" name="start-${date}" aria-label="Inicio de disponibilidad ${date}" value="${a?.start||'06:00'}" ${!a||readonly?'disabled':''} required><span class="subtle">a</span><input type="time" name="end-${date}" aria-label="Fin de disponibilidad ${date}" value="${a?.end||'22:00'}" ${!a||readonly?'disabled':''} required></div>`}).join('')}
function availabilityPage(){const r=db.refs.find(r=>r.id===refId);return head('SU SEMANA','¿Cuándo puede ir a la cancha?','Marque los días y las horas en los que puede arbitrar.')+`<section class="panel"><div class="panel-header"><div><h2>Disponibilidad semanal</h2><p>${esc(r.name)}</p></div>${weekButtons()}</div><form id="availability-form" class="availability"><div class="availability-help">Incluya tiempo suficiente para arbitrar el partido completo. Los administradores usarán esta información para proponerle nombramientos.</div>${availabilityRows(r)}<p class="form-error" id="availability-error" role="alert"></p><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">${icon('check')}Guardar disponibilidad</button><button class="btn secondary" type="button" data-action="weekend">Marcar fin de semana</button></div></form></section><p class="privacy-note">Cambiar su disponibilidad no cancela nombramientos confirmados. Si necesita un reemplazo, comuníquese con la asociación.</p>`}
function refereeHome(){const r=db.refs.find(r=>r.id===refId),mine=sorted(db.matches).flatMap(m=>m.slots.filter(s=>s.ref===refId&&active(s)).map(s=>({m,s}))),pending=mine.filter(x=>x.s.status==='pending'),accepted=mine.filter(x=>x.s.status==='accepted');return head('PORTAL DEL ÁRBITRO',`Hola, ${esc(r.name.split(' ')[0])}.`,'Sus invitaciones y próximos partidos, siempre a mano.')+`<div class="callout">${icon('calendar')}<div><strong>Su disponibilidad ayuda a organizar la jornada.</strong><p>Revise sus días disponibles antes de recibir un nuevo nombramiento.</p></div><div class="actions"><button class="btn secondary small" data-view="availability">Actualizar disponibilidad ${icon('arrow')}</button></div></div><div class="stats">${stat('Invitaciones por responder',pending.length,'Confirme o rechace cada solicitud','mail')}${stat('Partidos confirmados',accepted.length,'Consulte el día, la hora y el lugar','calendar')}${stat('Honorarios confirmados',money(accepted.reduce((a,x)=>a+x.s.fee,0)),'Suma de sus nombramientos aceptados','wallet')}${stat('Días disponibles',Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length,'En la semana actual del panel','clock')}</div><div class="section-title"><h2>Invitaciones pendientes</h2>${badge(`${pending.length} por responder`,'amber')}</div><div class="ref-matches">${pending.length?pending.map(x=>refMatch(x.m,x.s)).join(''):emptyState('Está al día.','Aquí aparecerán sus próximas invitaciones.','check')}</div><div class="section-title"><h2>Sus partidos confirmados</h2></div><div class="ref-matches">${accepted.length?accepted.map(x=>refMatch(x.m,x.s)).join(''):emptyState('Todavía no hay nombramientos confirmados.','Acepte una invitación para ver aquí el partido.')}</div><p class="privacy-note">Las invitaciones de esta demostración aparecen dentro de la aplicación. No se envían correos ni mensajes.</p>`}
function mapLinks(m){const coordinates=m.lat!==null&&m.lng!==null;return `<a class="btn secondary small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(coordinates?`${m.lat},${m.lng}`:m.venue)}" target="_blank" rel="noopener noreferrer">${icon('pin')}Google Maps</a><a class="btn secondary small" href="https://www.waze.com/ul?${coordinates?`ll=${encodeURIComponent(`${m.lat},${m.lng}`)}&navigate=yes`:`q=${encodeURIComponent(m.venue)}&navigate=yes`}" target="_blank" rel="noopener noreferrer">${icon('arrow')}Waze</a>`}
function refMatch(m,s){return `<article class="ref-match"><div class="match-top"><span class="tournament-tag">${esc(tournament(m)?.name)}</span>${statusBadge(s.status)}</div><div class="teams">${esc(m.home)}<span class="versus">vs</span>${esc(m.away)}</div><div class="subtle">Árbitro ${esc(s.role.toLowerCase())}</div><div class="match-meta"><span>${icon('calendar')}${dateLabel(m.date,{weekday:'long',day:'numeric',month:'long'})}</span><span>${icon('clock')}${esc(m.time)}–${endTime(m.time,m.duration)}</span></div><div class="match-meta"><span>${icon('pin')}${esc(m.venue)}</span></div><div class="fee">${money(s.fee)}<small>Honorarios de su nombramiento</small></div>${s.status==='pending'?`<div class="actions"><button class="btn primary small" data-action="accept" data-id="${m.id}" data-slot="${s.id}">${icon('check')}Aceptar partido</button><button class="btn danger small" data-action="reject" data-id="${m.id}" data-slot="${s.id}">Rechazar</button></div>`:`<div class="actions">${mapLinks(m)}</div><p class="subtle" style="line-height:1.6">${m.lat===null?'La ubicación abre una búsqueda por nombre; confirme la cancha con la asociación.':'Punto de demostración. Confirme la entrada de la cancha con la asociación.'}</p>`}</article>`}
function financePage(){const t=totals(db);return head('CONTROL ECONÓMICO','Las cuentas, claras','Registre los cobros a organizadores y los pagos a su equipo.',`<button class="btn secondary" data-action="export">${icon('download')}Exportar CSV</button>`)+`<div class="stats">${stat('Por cobrar',money(t.receivable),'Partidos pendientes de cobro','wallet')}${stat('Por pagar a árbitros',money(t.payable),'Solo nombramientos confirmados','people')}${stat('Pagado a árbitros',money(t.paid),'Pagos marcados en este registro','check')}${stat('Cobrado',money(db.matches.filter(m=>m.collected).reduce((a,m)=>a+m.charge,0)),'Cobros marcados como recibidos','wallet')}</div><div class="toolbar"><button class="btn ${financeTab==='charges'?'primary':'secondary'}" data-finance="charges">Cobros por partido</button><button class="btn ${financeTab==='payments'?'primary':'secondary'}" data-finance="payments">Pagos a árbitros</button><label class="subtle">Torneo <select id="finance-filter" aria-label="Filtrar cobros por torneo"><option value="all">Todos los torneos</option>${db.tournaments.map(t=>`<option value="${t.id}" ${tournamentFilter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><section class="panel"><div class="table-wrap">${financeTab==='charges'?chargesTable():paymentsTable()}</div></section><div class="footnote">${icon('info')}Este es un registro administrativo: marcar un pago no ejecuta transferencias bancarias ni emite facturas. Los totales superiores incluyen todos los torneos.</div>`}
function chargesTable(){return `<table><thead><tr><th>Partido / torneo</th><th>Fecha</th><th>Cobro al organizador</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${sorted(db.matches).filter(m=>tournamentFilter==='all'||m.tournament===tournamentFilter).map(m=>`<tr><td>${esc(m.home)} vs ${esc(m.away)}<small>${esc(tournament(m)?.name)}</small></td><td>${dateLabel(m.date)}</td><td class="cash-value">${money(m.charge)}</td><td>${badge(m.collected?'Cobrado':'Por cobrar',m.collected?'green':'amber')}</td><td><button class="btn secondary small" data-action="collect" data-id="${m.id}">${m.collected?'Deshacer cobro':'Marcar cobrado'}</button></td></tr>`).join('')||'<tr><td colspan="5">No hay partidos en este torneo.</td></tr>'}</tbody></table>`}
function paymentsTable(){const items=sorted(db.matches).filter(m=>tournamentFilter==='all'||m.tournament===tournamentFilter).flatMap(m=>m.slots.filter(s=>s.status==='accepted').map(s=>({m,s})));return `<table><thead><tr><th>Árbitro</th><th>Partido</th><th>Honorarios</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${items.map(({m,s})=>`<tr><td>${esc(refName(s.ref))}<small>${esc(s.role)}</small></td><td>${esc(m.home)} vs ${esc(m.away)}<small>${dateLabel(m.date)}</small></td><td class="cash-value">${money(s.fee)}</td><td>${badge(s.paid?'Pagado':'Pendiente',s.paid?'green':'amber')}</td><td><button class="btn secondary small" data-action="pay" data-id="${m.id}" data-slot="${s.id}">${s.paid?'Deshacer pago':'Marcar pagado'}</button></td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay nombramientos confirmados.</td></tr>'}</tbody></table>`}
function refHistory(){const items=sorted(db.matches).flatMap(m=>m.slots.filter(s=>s.ref===refId&&s.status==='accepted').map(s=>({m,s}))),paid=items.filter(x=>x.s.paid).reduce((a,x)=>a+x.s.fee,0),due=items.filter(x=>!x.s.paid).reduce((a,x)=>a+x.s.fee,0);return head('SUS HONORARIOS','Mis pagos','Consulte el registro de honorarios de sus nombramientos confirmados.')+`<div class="stats">${stat('Pendiente de pago',money(due),'Según el registro de la asociación','wallet')}${stat('Pagos registrados',money(paid),'Marcados por el administrador','check')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Partido</th><th>Fecha / puesto</th><th>Honorarios</th><th>Estado</th></tr></thead><tbody>${items.map(({m,s})=>`<tr><td>${esc(m.home)} vs ${esc(m.away)}<small>${esc(tournament(m)?.name)}</small></td><td>${dateLabel(m.date)}<small>${esc(s.role)}</small></td><td>${money(s.fee)}</td><td>${badge(s.paid?'Pago registrado':'Pendiente',s.paid?'green':'amber')}</td></tr>`).join('')||'<tr><td colspan="4">No hay honorarios confirmados todavía.</td></tr>'}</tbody></table></div></section><p class="privacy-note">El registro de la aplicación no sustituye un comprobante bancario. Consulte cualquier diferencia con la asociación.</p>`}
function openModal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="iconbtn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!$('#modal').open)$('#modal').showModal()}
const formFoot=(label='Guardar')=>`<p id="modal-error" class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn primary">${label}</button></div>`;
function matchModal(tournamentId){if(!db.tournaments.length){toast('Primero cree un torneo.');return}openModal('Nuevo partido',`<p class="hint">Registre la programación recibida del organizador. Después podrá enviar las invitaciones.</p><form id="match-form"><div class="form-grid"><label class="field full">Torneo<select name="tournament" required>${db.tournaments.map(t=>`<option value="${t.id}" ${t.id===tournamentId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="field">Equipo local<input name="home" maxlength="70" required></label><label class="field">Equipo visitante<input name="away" maxlength="70" required></label><label class="field">Fecha<input name="date" type="date" value="${addDays(week,5)}" required></label><label class="field">Hora de inicio<input name="time" type="time" value="09:00" required></label><label class="field">Bloque del partido (minutos)<input name="duration" type="number" min="30" max="240" step="5" value="120" required></label><label class="field">Equipo arbitral<select name="crew"><option value="3">Central y dos asistentes</option><option value="1">Solo central</option></select></label><label class="field full">Cancha y localidad<input name="venue" maxlength="150" placeholder="Ej. Cancha Central, localidad" required></label><label class="field">Latitud (opcional)<input name="lat" type="number" min="-90" max="90" step="any" placeholder="10.3233"></label><label class="field">Longitud (opcional)<input name="lng" type="number" min="-180" max="180" step="any" placeholder="-84.4307"></label><label class="field">Cobro al organizador (₡)<input name="charge" type="number" min="0" max="10000000" step="1" value="65000" required></label><label class="field">Honorarios del central (₡)<input name="central" type="number" min="0" max="1000000" step="1" value="22000" required></label><label class="field">Honorarios por asistente (₡)<input name="assistant" type="number" min="0" max="1000000" step="1" value="16000" required></label></div>${formFoot('Crear partido')}</form>`)}
function tournamentModal(id){const t=db.tournaments.find(t=>t.id===id);openModal(t?'Editar torneo y panel':'Nuevo torneo',`<p class="hint">Solo los árbitros del panel podrán recibir invitaciones de este torneo. Puede modificarlo después.</p><form id="tournament-form" data-id="${t?.id||''}"><div class="form-grid"><label class="field full">Nombre del torneo<input name="name" value="${esc(t?.name||'')}" maxlength="80" required></label><label class="field full">Organizador<input name="organizer" value="${esc(t?.organizer||'')}" maxlength="100" required></label><label class="field full">Modalidad y categoría<input name="category" value="${esc(t?.category||'Fútbol 11 · Libre')}" maxlength="80" required></label><div class="field full">Panel de árbitros<div class="checkgrid">${db.refs.map(r=>`<label><input type="checkbox" name="refs" value="${r.id}" ${!t||t.refs.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div></div></div>${formFoot(t?'Guardar cambios':'Crear torneo')}</form>`)}
function refModal(){openModal('Agregar árbitro',`<p class="hint">Se creará un perfil de demostración. No se enviará una invitación por correo.</p><form id="ref-form"><div class="form-grid"><label class="field full">Nombre completo<input name="name" maxlength="80" required></label><label class="field full">Correo electrónico<input name="email" type="email" maxlength="120" required></label><label class="field full">Categoría<select name="level"><option>Primera categoría</option><option>Segunda categoría</option><option>En formación</option></select></label></div>${formFoot('Agregar al panel')}</form>`)}
function assignmentModal(id){const m=db.matches.find(m=>m.id===id);openModal('Equipo arbitral',`<div class="tournament-tag">${esc(tournament(m)?.name)}</div><h3 style="margin:12px 0">${esc(m.home)} vs ${esc(m.away)}</h3><p class="hint">${dateLabel(m.date,{weekday:'long',day:'numeric',month:'long'})} · ${esc(m.time)}–${endTime(m.time,m.duration)}<br>${esc(m.venue)}<br>Se comprueba disponibilidad completa y un margen provisional de 45 minutos entre nombramientos. La categoría se muestra para que el administrador decida.</p>${m.slots.map(s=>slotEditor(m,s)).join('')}<p class="form-error" id="modal-error" role="alert"></p><div class="modal-foot"><button class="btn secondary" data-action="close">Listo</button></div>`)}
function slotEditor(m,s){if(active(s))return `<div class="slot-card"><div class="slot-head"><strong>${esc(s.role)} · ${money(s.fee)}</strong>${statusBadge(s.status)}</div><div class="person"><span class="avatar">${initials(refName(s.ref))}</span><b>${esc(refName(s.ref))}</b></div>${s.status==='pending'?`<button class="text-button" style="margin-top:12px" data-action="cancel-invite" data-id="${m.id}" data-slot="${s.id}">Retirar invitación</button>`:'<p class="subtle" style="margin-bottom:0">El árbitro ya aceptó el nombramiento.</p>'}</div>`;
 const candidates=db.refs.filter(r=>tournament(m)?.refs.includes(r.id)).map(r=>({r,...eligibility(db,r,m,s),load:db.matches.flatMap(x=>x.slots).filter(x=>x.ref===r.id&&active(x)).length})).sort((a,b)=>Number(b.ok)-Number(a.ok)||a.load-b.load||a.r.name.localeCompare(b.r.name));
 return `<div class="slot-card"><div class="slot-head"><strong>${esc(s.role)} · ${money(s.fee)}</strong>${statusBadge(s.status)}</div>${s.status==='rejected'?`<p class="hint" style="margin-bottom:10px">${esc(refName(s.ref))} rechazó esta invitación. Puede invitar a otra persona.</p>`:''}<div class="actions"><select id="candidate-${s.id}" aria-label="Árbitro para ${esc(s.role)}"><option value="">Seleccione un árbitro disponible</option>${candidates.map(c=>`<option value="${c.r.id}" ${c.ok?'':'disabled'}>${esc(c.r.name)} · ${esc(c.r.level)} · ${c.ok?`${c.load} nombramientos activos`:esc(c.reason)}</option>`).join('')}</select><button class="btn primary small" data-action="send" data-id="${m.id}" data-slot="${s.id}">Invitar</button></div>${!candidates.some(c=>c.ok)?'<p class="hint" style="margin:10px 0 0">No hay árbitros elegibles. Revise el panel del torneo o su disponibilidad.</p>':'<p class="subtle" style="margin-bottom:0">Disponibles ordenados por menor cantidad de nombramientos activos.</p>'}</div>`}
function exportCSV(){const lines=[['Tipo','Torneo','Partido','Fecha','Árbitro','Puesto','Monto CRC','Estado']];db.matches.forEach(m=>{lines.push(['Cobro',tournament(m)?.name,`${m.home} vs ${m.away}`,m.date,'','',m.charge,m.collected?'Cobrado':'Pendiente']);m.slots.filter(s=>s.status==='accepted').forEach(s=>lines.push(['Pago',tournament(m)?.name,`${m.home} vs ${m.away}`,m.date,refName(s.ref),s.role,s.fee,s.paid?'Pagado':'Pendiente']))});const safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-\t\r\n]/.test(s)?"'"+s:s).replace(/"/g,'""')+'"'};const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='A-cobros-y-pagos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Registro exportado.');}
document.addEventListener('click',event=>{
 const el=event.target.closest('button,[data-action]');if(!el)return;
 if(el.dataset.view){view=el.dataset.view;day='';query='';render();return}
 if(el.dataset.filter){filter=el.dataset.filter;render();return}
 if(el.dataset.day){day=day===el.dataset.day?'':el.dataset.day;render();return}
 if(el.dataset.finance){financeTab=el.dataset.finance;render();return}
 const action=el.dataset.action,id=el.dataset.id,slotId=el.dataset.slot;
 try{switch(action){
 case 'close':$('#modal').close();break;
 case 'week-prev':case 'week-next':week=addDays(week,action==='week-prev'?-7:7);day='';render();break;
 case 'week-today':week=monday(today());day='';render();break;
 case 'new-match':matchModal(id);break;
 case 'new-tournament':tournamentModal();break;
 case 'edit-tournament':tournamentModal(id);break;
 case 'new-ref':refModal();break;
 case 'assign':assignmentModal(id);break;
 case 'send':{const r=$(`#candidate-${slotId}`).value;if(!r)throw Error('Seleccione un árbitro disponible.');assign(db,id,slotId,r);log(`Invitación enviada a ${refName(r)}.`);render();assignmentModal(id);toast('Invitación disponible en el perfil del árbitro.');break}
 case 'cancel-invite':{const m=db.matches.find(m=>m.id===id),s=m.slots.find(s=>s.id===slotId);if(s.status!=='pending')throw Error('Esta invitación ya no está pendiente.');log(`Invitación retirada para ${refName(s.ref)}: ${m.home} vs ${m.away}.`);Object.assign(s,{ref:'',status:'empty',paid:false});persist();render();assignmentModal(id);break}
 case 'accept':case 'reject':{const m=db.matches.find(m=>m.id===id);respond(db,refId,id,slotId,action==='accept'?'accepted':'rejected');log(`${refName(refId)} ${action==='accept'?'aceptó':'rechazó'}: ${m.home} vs ${m.away}.`);render();toast(action==='accept'?'Partido confirmado. Ya puede consultar la ubicación.':'Invitación rechazada. El administrador puede asignar un reemplazo.');break}
 case 'unfilled':view='matches';filter='empty';day='';render();break;
 case 'as-ref':role='ref';refId=id;view='home';render();break;
 case 'see-availability':{const r=db.refs.find(r=>r.id===id);openModal(`Disponibilidad · ${esc(r.name)}`,`<p class="hint">${weekLabel(week)}. La disponibilidad se modifica desde el perfil del árbitro.</p>${availabilityRows(r,true)}<div class="modal-foot"><button class="btn primary" data-action="close">Cerrar</button></div>`);break}
 case 'weekend':{const form=$('#availability-form');for(let i=0;i<7;i++){const d=addDays(week,i),checked=i>=5;form.elements[`day-${d}`].checked=checked;form.elements[`start-${d}`].disabled=!checked;form.elements[`end-${d}`].disabled=!checked}toast('Fin de semana seleccionado. Guarde para aplicar.');break}
 case 'collect':{const m=db.matches.find(m=>m.id===id);m.collected=!m.collected;log(`Cobro ${m.collected?'registrado':'revertido'}: ${m.home} vs ${m.away}.`);render();toast('Registro de cobro actualizado.');break}
 case 'pay':{const m=db.matches.find(m=>m.id===id),s=m.slots.find(s=>s.id===slotId);if(s.status!=='accepted')throw Error('Solo se registran pagos de nombramientos confirmados.');s.paid=!s.paid;log(`Pago ${s.paid?'registrado':'revertido'} para ${refName(s.ref)}.`);render();toast('Registro de pago actualizado.');break}
 case 'export':exportCSV();break;
 case 'reset':openModal('Restablecer demostración',`<p class="hint">Se borrarán los cambios guardados en este navegador y volverán los datos ficticios iniciales.</p><div class="modal-foot"><button class="btn secondary" data-action="close">Conservar cambios</button><button class="btn danger" data-action="confirm-reset">Restablecer datos</button></div>`);break;
 case 'confirm-reset':db=seed();persist();role='admin';view='overview';week=monday(today());day='';filter='all';query='';tournamentFilter='all';$('#modal').close();render();toast('Demostración restablecida.');break;
 }}catch(error){if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=error.message;else toast(error.message)}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#match-list').innerHTML=matchList()}});
document.addEventListener('change',e=>{
 if(e.target.id==='role'){role=e.target.value==='admin'?'admin':'ref';if(role==='ref')refId=e.target.value;view=role==='admin'?'overview':'home';day='';query='';render()}
 if(e.target.id==='finance-filter'){tournamentFilter=e.target.value;render()}
 if(e.target.dataset.availability){const date=e.target.dataset.availability;const form=e.target.closest('form');if(form){form.elements[`start-${date}`].disabled=!e.target.checked;form.elements[`end-${date}`].disabled=!e.target.checked}}
});
document.addEventListener('submit',e=>{
 const form=e.target;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form),get=k=>String(f.get(k)||'').trim(),num=k=>Number(get(k));
 try{
 if(form.id==='match-form'){
  if(!get('home')||!get('away')||!get('venue'))throw Error('Complete los equipos y la cancha.');
  if(get('home').toLocaleLowerCase()===get('away').toLocaleLowerCase())throw Error('Los equipos deben ser diferentes.');
  if(minutes(get('time'))+num('duration')>1439)throw Error('El bloque del partido debe terminar antes de medianoche.');
  if((get('lat')==='')!==(get('lng')===''))throw Error('Ingrese ambas coordenadas o deje ambas vacías.');
  const roles=num('crew')===1?['Central']:['Central','Asistente 1','Asistente 2'];
  const m={id:uid(),tournament:get('tournament'),home:get('home'),away:get('away'),date:get('date'),time:get('time'),duration:num('duration'),venue:get('venue'),lat:get('lat')===''?null:num('lat'),lng:get('lng')===''?null:num('lng'),charge:num('charge'),collected:false,slots:roles.map((r,i)=>({id:uid(),role:r,ref:'',status:'empty',fee:num(i?'assistant':'central'),paid:false}))};
  db.matches.push(m);week=monday(m.date);day='';filter='all';query='';view='matches';log(`Partido creado: ${m.home} vs ${m.away}.`);$('#modal').close();render();toast('Partido creado. Ya puede asignar árbitros.');
 }else if(form.id==='tournament-form'){
  const refs=f.getAll('refs'),name=get('name');if(!name||!get('organizer')||!get('category'))throw Error('Complete los datos del torneo.');if(!refs.length)throw Error('Seleccione al menos un árbitro para el panel.');
  const id=form.dataset.id,t=db.tournaments.find(t=>t.id===id);
  if(t){const assigned=db.matches.filter(m=>m.tournament===id).flatMap(m=>m.slots).filter(active).map(s=>s.ref);if(assigned.some(r=>!refs.includes(r)))throw Error('Conserve en el panel a los árbitros con invitaciones o nombramientos activos.');Object.assign(t,{name,organizer:get('organizer'),category:get('category'),refs})}else db.tournaments.push({id:uid(),name,organizer:get('organizer'),category:get('category'),refs});
  log(`Torneo ${t?'actualizado':'creado'}: ${name}.`);$('#modal').close();render();toast('Torneo guardado.');
 }else if(form.id==='ref-form'){
  if(!get('name'))throw Error('Ingrese el nombre del árbitro.');if(db.refs.some(r=>r.email.toLowerCase()===get('email').toLowerCase()))throw Error('Este correo ya está registrado.');
  db.refs.push({id:uid(),name:get('name'),email:get('email'),level:get('level'),availability:{}});log(`Árbitro agregado: ${get('name')}.`);$('#modal').close();render();toast('Árbitro agregado. Asígnele torneos y registre su disponibilidad desde su perfil.');
 }else if(form.id==='availability-form'){
  const next={};for(let i=0;i<7;i++){const d=addDays(week,i);if(f.has(`day-${d}`)){const start=get(`start-${d}`),end=get(`end-${d}`);if(!start||!end||start>=end)throw Error(`Revise el horario del ${dateLabel(d)}: la hora final debe ser posterior a la inicial.`);next[d]={start,end}}}
  const r=db.refs.find(r=>r.id===refId);for(let i=0;i<7;i++)delete r.availability[addDays(week,i)];Object.assign(r.availability,next);log(`Disponibilidad actualizada: ${r.name}.`);render();toast('Disponibilidad semanal guardada.');
 }
 }catch(error){const target=form.id==='availability-form'?$('#availability-error'):$('#modal-error');if(target)target.textContent=error.message;else toast(error.message)}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close()}});
persist();render();
